.md-render .rapier-jump-label strong{font:inherit}
.md-render ul.rapier-jump-list{
	--md-jump-gap:calc(.9 * var(--md-unit));
	--md-jump-marker-inline-start:calc(-1.18 * var(--md-unit));
	--md-jump-marker-center:1em;
	list-style:none;
	padding-inline-start:calc(1.85 * var(--md-unit));
	margin:0 0 var(--md-line);
}
.md-render ul.rapier-jump-list>li{
	position:relative;
	margin:0 0 var(--md-jump-gap);
	padding:calc(.18 * var(--md-unit)) 0 calc(.18 * var(--md-unit)) calc(.15 * var(--md-unit));
}
.md-render ul.rapier-jump-list>li:last-child{margin-bottom:0}
.md-render ul.rapier-jump-list>li::before{
	content:'';
	position:absolute;
	inset-inline-start:var(--md-jump-marker-inline-start);
	top:calc(var(--md-jump-marker-center) - 5px);
